// 괄호 문자열 t가 올바른지 검사 (괄호 한 종류)
int depth = 0;
for (int i = 0; i < (int)t.size(); i++) {
    if (t[i] == '(') depth++;
    else depth--;
    if (depth < 0) return false;   // 여기서 실패
}
return depth == 0;

